#!/usr/bin/env python3
# patch-158-G4: parts per-asset (schema + UI)
"""
Make Parts addable per-asset. Previously parts were appointment-wide
and lived in a single bottom card. Now each asset card has its own
collapsible "Parts & products" section that scopes the part picker
and custom item form to that asset via appointment_asset_id.

What ships:

  Schema migration (000027):
    - Adds nullable appointment_asset_id to tenant_appointment_parts
    - nullOnDelete: detaching an asset leaves the parts unpinned
      rather than cascade-deleting them (preserves the chain/tube
      the mechanic already pulled from the wall)
    - Mirrors the items/addons pattern from 000025
    - Indexed as tap_asset_lookup for the per-asset query in show()

  Model changes:
    - TenantAppointmentPart: appointment_asset_id added to $fillable
      + appointmentAsset() BelongsTo relation
    - TenantAppointmentAsset: parts() HasMany relation (note: parts
      do NOT roll into the asset subtotal_cents like services do.
      They roll up into the appointment's parts_subtotal_cents.)

  Controller (no new ops, existing ops extended):
    - add_part: accepts optional appointment_asset_id (validated
      against the appointment's assets). Persists onto the part row.
    - add_custom_item: same extension.
    - show() (multi-asset branch): eager-loads parts.inventoryItem
      on each asset; computes $looseParts for parts with no asset FK.

  View changes (show-multi-asset.blade.php):
    - Per-asset collapsible Parts section inside each asset card:
      <details> with summary showing count, opens by default if
      that asset has parts. Inline part picker + custom item form.
      All bound to the asset via data-aa-id.
    - Standalone bottom Parts card renamed to "Unassigned parts".
      Only renders when $looseParts is non-empty (legacy back-compat
      for any pre-existing un-pinned parts on this appointment).
    - Old loose part picker DOM (id="ma-part-picker-input" etc.)
      removed. Its JS handler still exists but short-circuits when
      the DOM is gone — harmless dead code, cleanup deferred.

Single-asset appointments: when only one asset is attached, all the
Parts UI naturally pins to that one slot.

Standalone Python. Idempotent.
"""
import argparse, base64, pathlib, sys

MARKER = "MARKER-PATCH-158-G4"

